var n=`1185-frijoles-refritos`;var t=`world-1185`;var a=`MX`;var o=`central-america-caribbean`;var s=4;var r=474;var d={en:`Frijoles Refritos`,ua:`Смажена квасоля фріхолес`};var l={en:`Frijoles Refritos is a dish from Mexico prepared with pinto beans, yellow onion, garlic, queso fresco. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Смажена квасоля фріхолес, страва кухні країни Мексика, яку готують із таких продуктів: квасоля пінто, жовта цибуля, часник, кесо фреско. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Soak the dried beans in ample clean cold water for about 360 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 360 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:360,i:[[`pinto-beans`,420,`g`],[`water`,1050,`ml`]]},{en:`After soaking, drain the pinto beans and boil thoroughly in fresh water until tender; do not mash undercooked legumes.`,ua:`Після замочування злийте воду та добре проваріть пінто у свіжій воді до повної м’якості; не розминайте недоварені бобові.`,t:[`boiling`],m:90,i:[[`water`,1050,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`lard`,70,`g`],[`yellow-onion`,170,`g`],[`garlic`,4,`clove`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 10 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 10 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:10,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`queso-fresco`,85,`g`]]}];var u={slug:n,id:t,country:`MX`,region:o,servings:4,minutes:474,title:d,text:l,steps:h};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,n as slug,h as steps,l as text,d as title};